// Full small-block allocator composed with real row creation and page commitment. Zero additional address credit; prepared Win32 heap/reserve/commit endpoint semantics only.
using System;namespace Recovered.Gameplay {public static class PtlSmallPoolCPU {public static uint Allocate(SoundSetupImage m,uint size,Func<SoundSetupImage,uint,uint[],uint> leaf){Func<SoundSetupImage,uint,uint[],uint> route=null;route=delegate(SoundSetupImage image,uint address,uint[] args){if(address==0x6f1ce5)return PtlSmallPoolPages.Create(image,route);if(address==0x6f1d95)return PtlSmallPoolPages.Commit(image,args[0],route);return leaf(image,address,args);};return PtlSmallPoolAllocate.Allocate(m,size,route);}}}